    const tests = [];
    const test = (name, fn) => tests.push({ name, fn });
    const assert = (cond, msg) => { if (!cond) throw new Error(msg); };
    const near = (a, b, tol = 3) => Math.abs(a - b) <= tol;

    // ===== テストコンテキスト（iframe内のアプリを操作するヘルパー群） =====
    function makeCtx(frame) {
        const W = frame.contentWindow;
        const D = frame.contentDocument;
        const svg = D.getElementById('chem-svg');
        const toClient = (x, y) => {
            const pt = new W.DOMPoint(x, y).matrixTransform(svg.getScreenCTM());
            return { clientX: pt.x, clientY: pt.y };
        };
        const pe = (type, opts = {}) => new W.PointerEvent(type, {
            bubbles: true, cancelable: true, pointerId: 1, pointerType: 'mouse',
            button: opts.button ?? 0, clientX: opts.clientX, clientY: opts.clientY
        });
        const clickAt = (x, y, button = 0) => {
            const ev = toClient(x, y);
            svg.dispatchEvent(pe('pointerdown', { ...ev, button }));
            W.dispatchEvent(pe('pointerup', { ...ev, button }));
        };
        const hoverAt = (x, y) => svg.dispatchEvent(pe('pointermove', toClient(x, y)));
        const dragBond = (hitEl, fromXY, toXY) => {
            hitEl.dispatchEvent(pe('pointerdown', toClient(fromXY.x, fromXY.y)));
            svg.dispatchEvent(pe('pointermove', toClient(toXY.x, toXY.y)));
            W.dispatchEvent(pe('pointerup', toClient(toXY.x, toXY.y)));
        };
        const hitbox = (i) => D.querySelectorAll('.svg-bond-hitbox')[i];
        const tick = (ms = 15) => new Promise(r => setTimeout(r, ms));
        const reset = () => {
            const g = W.game;
            // 初回ヒント（結合タップの案内）が他テストの途中で不意に発火しないよう既読にしておく
            // （R3が明示的にフラグを消して検証する）
            W.localStorage.setItem('chemHintBondToggle', '1');
            if (W.reactionPlayer && W.reactionPlayer.active) W.reactionPlayer.exit();
            if (g.setMode) g.setMode('puzzle');
            g.loadStage(0);
            g.selectedTool = 'select';
            g.selectedAtomType = 'C';
            g.asymmetricMode = false;
            g.judgeAsymmetric = false;
            g.reshapeMode = false;
            g._reshapeLastBond = null;
            // 「🎯 反応させる分子を選ぶ」も他のタップ横取りモードと同じく落としておく（v1409）。
            // ON のまま次のテストへ漏れると、**キャンバスのタップが全部選択に化けて**
            // 作図系のテストがまとめて赤くなる（原因が症状から読めない型）
            if (g.deactivateReactionSelectMode) g.deactivateReactionSelectMode();
            g.userMolecule = new W.Molecule();
            g.updateDrawing();
            D.getElementById('verify-result').classList.add('hidden');
        };
        return { W, D, svg, toClient, pe, clickAt, hoverAt, dragBond, hitbox, tick, reset,
                 get game() { return W.game; } };
    }

    // ===== 全件掃き出しの足場（描画を止めて回す） =====
    //
    // 名称ライブラリの**全件**に `summonMolecule` を掛ける検査が3つある
    // （RF2 の再現性・RF3 の詰まり・RX10b の貫通）。登録は 898 エントリ／別名込み 956 通りで、
    // 反応ルールは 35 本あるので、素直に回すと呼び出しは千回〜数千回になる。
    //
    // **実測（v925・計測の足場を入れて調べた）**: 956 件を1周する 8.1 秒の内訳は
    //   updateDrawing（SVG の描き直し） 4.4 秒 ／ fitCanvasToMolecule（viewBox の再計算） 2.6 秒 ／
    //   saveState（Undo 履歴のディープコピー） 1.0 秒 ／ **座標を決める計算そのものは 0.14 秒**。
    // つまり 98% が「画面に出す」ぶんで、これらの検査が見ている
    // **原子の座標と結合（トポロジーと幾何）には一切関わらない**。
    //
    // そこで掃き出しのあいだだけ描画系を止める。**判定も母数も件数も変えていない**
    // ―― 止めるのは描く仕事だけで、座標を決める `reshapeVinylAngles` や
    // 反応の `execute` はそのまま本物が走る。
    // 描画そのものは他の 290 件超のテストが実イベントで通しているうえ、
    // 各テストは**代表を数件、描画ありのまま**残して同じ検査に掛けている
    // （＝描画ありと描画なしで結果が変わらないことを、テスト自身が突き合わせている）。
    const QUIET_KEYS = ['updateDrawing', 'fitCanvasToMolecule', 'saveState', 'showToast'];
    function withoutRendering(c, fn) {
        const g = c.game;
        // 覆いには目印を付ける。**「自前のプロパティかどうか」では見分けられない**
        // ―― 別のテスト（RX9）が原型のメソッドを自前プロパティとして置き直しているため
        const saved = QUIET_KEYS.map(k => [k, Object.prototype.hasOwnProperty.call(g, k), g[k]]);
        QUIET_KEYS.forEach(k => {
            const stub = () => {};
            stub._quietStub = true;
            g[k] = stub;
        });
        try {
            return fn();
        } finally {
            saved.forEach(([k, wasOwn, fn0]) => {
                delete g[k];
                if (wasOwn) g[k] = fn0;
            });
        }
    }
    // 覆いが本当に外れたか（外れないと以後のテストが「描いていないのに緑」になる）。
    // 掃き出しを使うテストは最後にこれを呼ぶ
    function assertRenderingRestored(c) {
        const g = c.game;
        QUIET_KEYS.forEach(k => {
            assert(typeof g[k] === 'function', `${k} が失われている`);
            assert(!g[k]._quietStub,
                `${k} の差し替えが残っている（描画が止まったまま後続テストへ漏れる）`);
        });
        // 実際に描けることまで見る（関数が居るだけでは足りない）
        g.userMolecule = new c.W.Molecule();
        g.summonMolecule('エタノール');
        assert(c.D.querySelectorAll('#chem-svg .svg-atom-node').length > 0,
            '描画を戻したのに原子が1つも描かれない（覆いが外れていない）');
        g.userMolecule = new c.W.Molecule();
        g.updateDrawing();
    }

    // ===== A. 基盤 =====

    test('A1: アプリ起動とデータロード（ステージ56+・反応4本）', async (c) => {
        assert(c.W.game, 'game が初期化されていない');
        assert(c.W.STAGES.length >= 56, `STAGES が ${c.W.STAGES.length} 件（56件以上を期待）`);
        assert(c.W.reactionPlayer && c.W.reactionPlayer.reactions.length >= 4,
            '反応データが4本ロードされていない');
        assert(c.W.COMPOUNDS && c.W.COMPOUNDS.length >= 20,
            `名称判定ライブラリ(compounds.json)が ${c.W.COMPOUNDS ? c.W.COMPOUNDS.length : 0} 件`);
    });

    test('A2: 座標変換の誤差ゼロ（getScreenCTM準拠・5点）', async (c) => {
        const rect = c.svg.getBoundingClientRect();
        const pts = [
            [rect.left + rect.width / 2, rect.top + 20],
            [rect.left + rect.width / 2, rect.bottom - 20],
            [rect.left + 20, rect.top + rect.height / 2],
            [rect.right - 20, rect.top + rect.height / 2],
            [rect.left + 20, rect.top + 20]
        ];
        pts.forEach(([cx, cy]) => {
            const code = c.game.getSnappedCoords({ clientX: cx, clientY: cy });
            const pt = new c.W.DOMPoint(cx, cy).matrixTransform(c.svg.getScreenCTM().inverse());
            assert(near(code.rawX, pt.x, 0.5) && near(code.rawY, pt.y, 0.5),
                `座標変換誤差: (${(code.rawX - pt.x).toFixed(1)}, ${(code.rawY - pt.y).toFixed(1)})`);
        });
    });

    test('A3: 全ステージ＋名称ライブラリの自己整合', async (c) => {
        const failures = [];
        [...c.W.STAGES, ...c.W.COMPOUNDS].forEach(entry => {
            const target = c.game.createTargetFromData(entry);
            const user = c.game.createTargetFromData(entry);
            if (!c.W.verifyMolecule(user, target)) failures.push(entry.name);
        });
        assert(failures.length === 0, `不整合エントリ: ${failures.join(', ')}`);
    });

    test('A4: 水ステージを実イベントでクリアできる', async (c) => {
        c.reset();
        c.game.selectedAtomType = 'O';
        c.clickAt(400, 300);
        assert(c.W.verifyMolecule(c.game.userMolecule, c.game.createTargetFromData(c.W.STAGES[0])),
            '水（O 1個配置）が正解にならない');
    });

    // ===== B. 検証ロジック =====

    test('B1: ケクレ位相の吸収（o-キシレン両位相とも正解）', async (c) => {
        const target = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === 'o-キシレン'));
        [1, 0].forEach(attachBase => {
            const u = new c.W.Molecule();
            const ring = [];
            for (let i = 0; i < 6; i++) ring.push(u.addAtom('C', 400 + 42 * Math.cos(i * Math.PI / 3), 300 + 42 * Math.sin(i * Math.PI / 3)));
            for (let i = 0; i < 6; i++) u.addBond(ring[i].id, ring[(i + 1) % 6].id, i % 2 === 0 ? 2 : 1);
            const m1 = u.addAtom('C', 500, 300);
            const m2 = u.addAtom('C', 500, 350);
            u.addBond(ring[attachBase].id, m1.id, 1);
            u.addBond(ring[attachBase + 1].id, m2.id, 1);
            assert(c.W.verifyMolecule(u, target), `ケクレ位相 attachBase=${attachBase} で不正解`);
        });
    });

    test('B2: 負例が不正解のまま（メタ配置/酢酸の次数違い/シクロヘキサン）', async (c) => {
        const oxy = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === 'o-キシレン'));
        const u1 = new c.W.Molecule();
        const r1 = [];
        for (let i = 0; i < 6; i++) r1.push(u1.addAtom('C', 400 + 42 * Math.cos(i * Math.PI / 3), 300 + 42 * Math.sin(i * Math.PI / 3)));
        for (let i = 0; i < 6; i++) u1.addBond(r1[i].id, r1[(i + 1) % 6].id, i % 2 === 0 ? 2 : 1);
        u1.addBond(r1[0].id, u1.addAtom('C', 500, 300).id, 1);
        u1.addBond(r1[2].id, u1.addAtom('C', 500, 350).id, 1);
        assert(!c.W.verifyMolecule(u1, oxy), 'メタ配置が o-キシレンとして正解になった');

        const acetic = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === '酢酸'));
        const u2 = new c.W.Molecule();
        const c1 = u2.addAtom('C', 360, 300), c2 = u2.addAtom('C', 400, 300);
        const oA = u2.addAtom('O', 400, 260), oB = u2.addAtom('O', 440, 300);
        u2.addBond(c1.id, c2.id, 1);
        u2.addBond(c2.id, oA.id, 1); // 本来は二重結合
        u2.addBond(c2.id, oB.id, 1);
        assert(!c.W.verifyMolecule(u2, acetic), '結合次数違いの酢酸が正解になった');

        const tol = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === 'トルエン'));
        const u3 = new c.W.Molecule();
        const r3 = [];
        for (let i = 0; i < 6; i++) r3.push(u3.addAtom('C', 400 + 42 * Math.cos(i * Math.PI / 3), 300 + 42 * Math.sin(i * Math.PI / 3)));
        for (let i = 0; i < 6; i++) u3.addBond(r3[i].id, r3[(i + 1) % 6].id, 1);
        u3.addBond(r3[0].id, u3.addAtom('C', 500, 300).id, 1);
        assert(!c.W.verifyMolecule(u3, tol), 'メチルシクロヘキサンがトルエンとして正解になった');
    });

    test('B3: -NO2モジュールでニトロベンゼンがクリア可能', async (c) => {
        c.reset();
        const idx = c.W.STAGES.findIndex(s => s.name === 'ニトロベンゼン');
        c.game.loadStage(idx);
        c.game.placeModule('benzene', 400, 300, null);
        const ring = c.game.userMolecule.atoms.filter(a => a.element === 'C');
        c.game.placeModule('no2', ring[0].x, ring[0].y, ring[0]);
        assert(c.W.verifyMolecule(c.game.userMolecule, c.game.createTargetFromData(c.W.STAGES[idx])),
            'モジュールで組んだニトロベンゼンが不正解');
    });

    test('B4: 自動水素数（アセチレン[1,1]・アセトニトリル C:3,C:0,N:0）', async (c) => {
        const acet = c.game.createTargetFromData(c.W.STAGES.find(s => s.name.startsWith('アセチレン')));
        assert(acet.atoms.every(a => acet.getFreeValency(a.id) === 1), 'アセチレンのH数が[1,1]でない');
        const mecn = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === 'アセトニトリル'));
        const h = mecn.atoms.map(a => `${a.element}:${mecn.getFreeValency(a.id)}`).join(',');
        assert(h === 'C:3,C:0,N:0', `アセトニトリルのH数が ${h}`);
    });

    test('B5: アラニンのα炭素のみ不斉判定', async (c) => {
        const ala = c.game.createTargetFromData(c.W.STAGES.find(s => s.name === 'アラニン'));
        assert(ala.isAsymmetricCarbon(ala.atoms[1].id), 'α炭素が不斉と判定されない');
        assert(!ala.isAsymmetricCarbon(ala.atoms[0].id), 'メチル炭素が不斉と誤判定');
    });

    test('B6: 環原子の元素置換でピリジンがクリア可能（O置換は価標ブロック）', async (c) => {
        c.reset();
        const idx = c.W.STAGES.findIndex(s => s.name === 'ピリジン');
        c.game.loadStage(idx);
        c.game.placeModule('benzene', 400, 300, null);
        c.game.selectedAtomType = 'N';
        const ringAtom = c.game.userMolecule.atoms[0];
        c.clickAt(ringAtom.x, ringAtom.y);
        assert(ringAtom.element === 'N', '環CがNに置換されない');
        assert(c.W.verifyMolecule(c.game.userMolecule, c.game.createTargetFromData(c.W.STAGES[idx])),
            'ピリジンが不正解');
        c.game.selectedAtomType = 'O';
        const ringC = c.game.userMolecule.atoms[1];
        c.clickAt(ringC.x, ringC.y);
        assert(ringC.element === 'C', '価標超過のO置換がブロックされない');
    });

    test('B7: 三重結合の端のHは反対側180°に配置（エチン/プロピン）', async (c) => {
        // エテン→エチンのトグル時、Hが90°（垂直）に付く不具合の再発防止（2026-07-21 ユーザー報告）
        const m = new c.W.Molecule();
        const a = m.addAtom('C', 379, 300);
        const b = m.addAtom('C', 421, 300);
        m.addBond(a.id, b.id, 3);
        const hs = m.calculateHydrogens();
        assert(hs.length === 2, `エチンのH数が ${hs.length}（2を期待）`);
        const ha = hs.find(h => h.parentId === a.id);
        const hb = hs.find(h => h.parentId === b.id);
        assert(ha && ha.x < a.x && Math.abs(ha.y - 300) < 1, '左CのHが三重結合の反対側（左・直線上）にない');
        assert(hb && hb.x > b.x && Math.abs(hb.y - 300) < 1, '右CのHが三重結合の反対側（右・直線上）にない');

        // プロピン末端CのHも直線上（H–C≡C–CH3）
        const p = new c.W.Molecule();
        const c1 = p.addAtom('C', 358, 300);
        const c2 = p.addAtom('C', 400, 300);
        const c3 = p.addAtom('C', 442, 300);
        p.addBond(c1.id, c2.id, 3);
        p.addBond(c2.id, c3.id, 1);
        const h1 = p.calculateHydrogens().find(h => h.parentId === c1.id);
        assert(h1 && h1.x < c1.x && Math.abs(h1.y - 300) < 1, 'プロピン末端CのHが直線上にない');
    });

    test('B8: 二重結合の端の自動Hは空き結合手の数まで（イミンのNがNH₂表示になる不具合）', async (c) => {
        // CH₂=NH（メタンイミン）: C-N を二重結合にしたとき、N のHは1個（2026-07-24 ユーザー報告）
        const m = new c.W.Molecule();
        const cAtom = m.addAtom('C', 400, 300);
        const nAtom = m.addAtom('N', 442, 300);
        m.addBond(cAtom.id, nAtom.id, 2);
        const hs = m.calculateHydrogens();
        const cH = hs.filter(h => h.parentId === cAtom.id).length;
        const nH = hs.filter(h => h.parentId === nAtom.id).length;
        assert(cH === 2, `C=N端のCのH数が ${cH}（2を期待）`);
        assert(nH === 1, `C=N端のNのH数が ${nH}（1を期待。NH₂表示の再発）`);
        // 描画のH数と分子式のH数が一致する（CH₃N）
        assert(cH + nH === 3, `描画H合計 ${cH + nH} が分子式CH₃Nと不一致`);

        // 回帰確認: C=C 端の炭素は従来どおり2個（エテンのH合計4）
        const e = new c.W.Molecule();
        const e1 = e.addAtom('C', 400, 300);
        const e2 = e.addAtom('C', 442, 300);
        e.addBond(e1.id, e2.id, 2);
        assert(e.calculateHydrogens().length === 4, 'エテンの自動Hが4個でない');

        // ケトンの O（空き手0）にHが付かないことも確認（C=O）
        const k = new c.W.Molecule();
        const k1 = k.addAtom('C', 400, 300);
        const k2 = k.addAtom('O', 442, 300);
        k.addBond(k1.id, k2.id, 2);
        assert(k.calculateHydrogens().filter(h => h.parentId === k2.id).length === 0,
            'C=OのOにHが付いている');
    });

    // ===== C. 編集操作 =====

    test('C1: プレビュー＝実結合（2原子隣接の交点で2本）', async (c) => {
        c.reset();
        c.game.userMolecule.addAtom('C', 336, 294);
        c.game.userMolecule.addAtom('C', 378, 336);
        c.game.updateDrawing();
        c.hoverAt(378, 294);
        const previewLines = c.D.querySelectorAll('#ui-group line').length;
        c.clickAt(378, 294);
        const newAtom = c.game.userMolecule.atoms[2];
        const actual = c.game.userMolecule.getBondsForAtom(newAtom.id).length;
        assert(previewLines === 2 && actual === 2, `プレビュー${previewLines}本 vs 実結合${actual}本`);
    });

    test('C2: 4つ目のCで四員環が閉じシクロブタン判定', async (c) => {
        c.reset();
        c.clickAt(336, 294);
        c.clickAt(378, 294);
        c.clickAt(378, 336);
        c.clickAt(336, 336);
        assert(c.game.userMolecule.atoms.length === 4 && c.game.userMolecule.bonds.length === 4, '四員環が閉じない');
        const m = new c.W.Molecule();
        const cs = [m.addAtom('C', 0, 0), m.addAtom('C', 42, 0), m.addAtom('C', 42, 42), m.addAtom('C', 0, 42)];
        for (let i = 0; i < 4; i++) m.addBond(cs[i].id, cs[(i + 1) % 4].id, 1);
        assert(c.W.verifyMolecule(c.game.userMolecule, m), 'シクロブタンとして判定されない');
    });

    test('C3: Cl（価標1）は2隣接点でも結合1本のみ', async (c) => {
        c.reset();
        c.game.userMolecule.addAtom('C', 336, 294);
        c.game.userMolecule.addAtom('C', 378, 336);
        c.game.updateDrawing();
        c.game.selectedAtomType = 'Cl';
        c.clickAt(378, 294);
        const cl = c.game.userMolecule.atoms.find(a => a.element === 'Cl');
        assert(cl && c.game.userMolecule.getBondsForAtom(cl.id).length === 1,
            'Clの結合数が価標を超えた');
    });

    test('C4: プロパン中央Cの削除で両端が残る（巻き添え削除なし）', async (c) => {
        c.reset();
        const a = c.game.userMolecule.addAtom('C', 358, 300);
        const b = c.game.userMolecule.addAtom('C', 400, 300);
        const d = c.game.userMolecule.addAtom('C', 442, 300);
        c.game.userMolecule.addBond(a.id, b.id, 1);
        c.game.userMolecule.addBond(b.id, d.id, 1);
        c.game.updateDrawing();
        c.game.selectedTool = 'erase';
        c.clickAt(b.x, b.y);
        assert(c.game.userMolecule.atoms.length === 2, `残存原子が ${c.game.userMolecule.atoms.length} 個`);
    });

    test('C5: Undoで不斉マークが復元される', async (c) => {
        c.reset();
        const atom = c.game.userMolecule.addAtom('C', 400, 300);
        atom.isAsymmetricMarked = true;
        c.game.saveState();
        atom.isAsymmetricMarked = false;
        c.game.undo();
        assert(c.game.userMolecule.atoms[0].isAsymmetricMarked, 'Undoでマークが消えた');
    });

    test('C6: 空振り操作でUndo履歴を消費しない', async (c) => {
        c.reset();
        c.game.userMolecule.addAtom('C', 400, 300);
        c.game.updateDrawing();
        c.game.selectedTool = 'erase';
        const before = c.game.history.length;
        c.clickAt(150, 150); // 何もない場所
        assert(c.game.history.length === before, '消しゴム空振りで履歴が増えた');
        c.game.userMolecule = new c.W.Molecule();
        c.game.updateDrawing();
        const before2 = c.game.history.length;
        c.D.getElementById('btn-clear-all').click();
        assert(c.game.history.length === before2, '空の全消去で履歴が増えた');
    });

    test('C7: 右クリックで原子削除・右ドラッグはパン', async (c) => {
        c.reset();
        const a = c.game.userMolecule.addAtom('C', 379, 300);
        const b = c.game.userMolecule.addAtom('C', 421, 300);
        c.game.userMolecule.addBond(a.id, b.id, 1);
        c.game.updateDrawing();
        c.clickAt(a.x, a.y, 2); // 右クリック（移動なし）
        assert(c.game.userMolecule.atoms.length === 1, '右クリックで原子が削除されない');
        const vbx = c.svg.viewBox.baseVal.x;
        const g1 = c.toClient(b.x, b.y);
        c.svg.dispatchEvent(c.pe('pointerdown', { ...g1, button: 2 }));
        c.svg.dispatchEvent(c.pe('pointermove', { clientX: g1.clientX + 60, clientY: g1.clientY + 40, button: 2 }));
        c.W.dispatchEvent(c.pe('pointerup', { clientX: g1.clientX + 60, clientY: g1.clientY + 40, button: 2 }));
        assert(Math.abs(c.svg.viewBox.baseVal.x - vbx) > 1, '右ドラッグでパンしない');
        assert(c.game.userMolecule.atoms.length === 1, '右ドラッグで原子が消えた');
    });

    test('C8: スペース不足時は配置禁止（noSpace）＋トースト', async (c) => {
        c.reset();
        c.game.userMolecule.addAtom('C', 336, 294);
        for (let x = 372; x <= 428; x += 6) {
            const n1 = c.game.userMolecule.addAtom('N', x, 273);
            const n2 = c.game.userMolecule.addAtom('N', x, 231);
            c.game.userMolecule.addBond(n1.id, n2.id, 3); // 飽和ブロッカー
        }
        c.game.updateDrawing();
        const mouse = c.toClient(365, 301);
        const coords = c.game.getSnappedCoords({ clientX: mouse.clientX, clientY: mouse.clientY });
        assert(coords.isValid === false && coords.noSpace === true, 'noSpaceにならない');
        const before = c.game.userMolecule.atoms.length;
        c.clickAt(365, 301);
        assert(c.game.userMolecule.atoms.length === before, '配置がブロックされない');
        // v1110 で文言を「近すぎます」に変えた（4通りの外し方を言い分けるため。PW1 が本体）。
        // 伸長で空間を作れる、という逃げ道の案内はそのまま残す
        assert(coords.reason === 'overlap', `理由が overlap にならない（${coords.reason}）`);
        const said = c.D.getElementById('verify-result').textContent;
        assert(said.includes('近すぎ') && said.includes('結合線をドラッグ'),
            `案内トーストが出ない: 「${said}」`);
    });

    test('C9: 結合クリックで次数トグル（エタン→エテン→エチン）', async (c) => {
        // v83退行の再発防止: 純クリック時にヒットラインが再生成されると
        // clickイベントが元要素に届かず、トグルが動かなくなる。
        // 「down+up後も要素がDOMに残っている」ことが実ブラウザでclickが届く条件。
        c.reset();
        c.clickAt(336, 294);
        c.clickAt(378, 294); // エタン（C-C 単結合）
        const bond = c.game.userMolecule.bonds[0];
        const mid = c.toClient(357, 294);
        const clickBond = async () => {
            const hit = c.D.querySelector('.svg-bond-hitbox');
            hit.dispatchEvent(c.pe('pointerdown', mid));
            c.W.dispatchEvent(c.pe('pointerup', mid));
            assert(hit.isConnected, 'クリック処理中にヒットラインが再生成された（clickが届かない）');
            hit.dispatchEvent(new c.W.MouseEvent('click', { ...mid, bubbles: true }));
            await c.tick();
        };
        await clickBond();
        assert(bond.type === 2, `1回目のクリックで二重結合にならない（type=${bond.type}）`);
        await clickBond();
        assert(bond.type === 3, `2回目のクリックで三重結合にならない（type=${bond.type}）`);
    });

    // ===== PW. 置けなかったクリックの理由（v1110・発注書「作図の当たり判定」要望A） =====
    //
    // `getSnappedCoords` は理由を計算しているのに呼び出し側が捨てており、
    // **近傍原子なし** と **ベンゼンの置換基点の重なり** は画面に何も出さずに落ちていた。
    // また `tooLarge` の案内は隠しの互換パネル（#panel-legacy＝1px に切り抜き）へ
    // 書いていたので、**一度も画面に出ていなかった**。ここはその再発検出。

    // 空き価標0の壁（CO2）。吸着候補にならず、MIN_CLEARANCE の相手にはなる
    const wallCO2 = (c, x, y, dx, dy) => {
        const m = c.game.userMolecule;
        const a = m.addAtom('C', x, y);
        const o1 = m.addAtom('O', x + dx, y + dy);
        const o2 = m.addAtom('O', x - dx, y - dy);
        m.addBond(a.id, o1.id, 2);
        m.addBond(a.id, o2.id, 2);
    };
    // 破壊操作にならない距離（ATOM_TAP_RADIUS の外）で、狙った理由になる点を総当たりで探す。
    // 判定の帯そのものは動くので、**座標を決め打ちしない**
    // （v1130: 削除の半径が 28px → 18px になり、吸着半径が 45px → 63px になったので範囲を広げた）
    const findMissSpot = (c, ax, ay, want) => {
        for (let r = 19; r <= 60; r += 1) {
            for (let a = 0; a < 360; a += 5) {
                const x = ax + r * Math.cos(a * Math.PI / 180);
                const y = ay + r * Math.sin(a * Math.PI / 180);
                if (c.game.findNearestAtomAt(x, y, c.W.HIT_AREAS.atomTapRadius)) continue;
                // v1180: ロック原子・ベンゼン環内の原子の 18〜28px を避ける除外は**外した**。
                // 1原子のドラッグを廃止したので、この帯も他の原子と同じく配置経路へ落ちる
                const co = c.game.getSnappedCoords(c.toClient(x, y));
                if (co.isValid) continue;
                if (want.reason && co.reason !== want.reason) continue;
                if (want.stolen === true && !co.stolen) continue;
                if (want.stolen === false && co.stolen) continue;
                return { x, y, coords: co };
            }
        }
        return null;
    };
    const missReset = (c) => {
        c.game.clearPlaceMissMark();
        c.game._missMsg = null;
        c.game._missAt = 0;
        const t = c.D.getElementById('canvas-toast');
        t.className = 'hidden';
        t.textContent = '';
    };
    const toastText = (c) => {
        const t = c.D.getElementById('canvas-toast');
        return t.classList.contains('hidden') ? '' : t.textContent;
    };

    // 自由配置でクリアランスを割る場面（v1130）。空き価標0の壁のそばを押す ——
    // 壁は吸着の候補にならないので、タップは「新しい分子を置く」経路へ落ち、
    // グリッドに丸めた点が壁に近すぎて弾かれる
    const crowdedScene = (c, cx = 420, cy = 300) => {
        c.reset();
        wallCO2(c, cx, cy, 42, 0);
        c.game.updateDrawing();
        const spot = findMissSpot(c, cx, cy, { reason: 'crowded' });
        assert(spot, '自由配置のクリアランス違反になる点が作れなかった');
        return spot;
    };

    test('PW1: 置けなかった4通りが、それぞれ違う理由を字幕に出す', async (c) => {
        const said = {};

        // (a) **置ける**（自由配置。v1130・DESIGN_hit_areas.md 決定1／要望D）。
        //     もとは「近傍原子なし」を isValid:false('far') で捨てていた（＝無言のタップ）。
        //     いまは離れた場所は**新しい分子の置き場所**なので、原子が増えて字幕は出ないのが正しい
        c.reset();
        c.game.userMolecule.addAtom('C', 400, 300);
        c.game.updateDrawing();
        missReset(c);
        c.clickAt(600, 300);
        await c.tick();
        assert(c.game.userMolecule.atoms.filter(a => a.element !== 'H').length === 2,
            '離れた場所のクリックで原子が増えない（自由配置になっていない）');
        assert(toastText(c) === '',
            `自由配置なのに字幕が出た: 「${toastText(c)}」`);
        assert(c.D.getElementById('miss-group').children.length === 0,
            '自由配置なのに「外した」しるしが出た');
        assert(c.game.countMolecules() === 2, '別の分子として置かれていない');

        // (a2) 近すぎ（自由配置） … どの原子とも競わない遠さだが、丸めた点が となりに近すぎる。
        //      「結合線を伸ばす」逃げ道が効かない場面なので (b) とは言い方を変える
        const s1 = crowdedScene(c);
        missReset(c);
        const before1 = c.game.userMolecule.atoms.length;
        c.clickAt(s1.x, s1.y);
        await c.tick();
        said.crowded = toastText(c);
        assert(c.game.userMolecule.atoms.length === before1, '近すぎ（自由配置）のクリックで原子が増えた');

        // (b) 近すぎ … 42〜84px どこへ延ばしても隣と重なる
        c.reset();
        c.game.userMolecule.addAtom('C', 400, 300);
        wallCO2(c, 380, 240, 42, 0);
        wallCO2(c, 400, 196, 42, 0);
        c.game.updateDrawing();
        missReset(c);
        const s2 = findMissSpot(c, 400, 300, { reason: 'overlap' });
        assert(s2, '「近すぎ」になる点が作れなかった（場面の作り方が古い）');
        const before2 = c.game.userMolecule.atoms.length;
        c.clickAt(s2.x, s2.y);
        await c.tick();
        said.overlap = toastText(c);
        assert(c.game.userMolecule.atoms.length === before2, '近すぎのクリックで原子が増えた');

        // (c) 空きなし … 四方の候補点が全部ふさがっている
        c.reset();
        c.game.userMolecule.addAtom('C', 400, 300);
        let prev = null, first = null;
        [[442, 300], [358, 300], [400, 342], [400, 258]].forEach(([x, y]) => {
            const o = c.game.userMolecule.addAtom('O', x, y);
            if (prev) c.game.userMolecule.addBond(prev.id, o.id, 1); else first = o;
            prev = o;
        });
        c.game.userMolecule.addBond(prev.id, first.id, 1); // 環にして全部を空き価標0にする
        c.game.updateDrawing();
        missReset(c);
        const s3 = findMissSpot(c, 400, 300, { reason: 'blocked' });
        assert(s3, '「空きなし」になる点が作れなかった');
        const before3 = c.game.userMolecule.atoms.length;
        c.clickAt(s3.x, s3.y);
        await c.tick();
        said.blocked = toastText(c);
        assert(c.game.userMolecule.atoms.length === before3, '空きなしのクリックで原子が増えた');

        // (d) キャンバス上限 … もとは隠しパネルにしか書いておらず画面に出ていなかった
        c.reset();
        c.game.userMolecule.addAtom('C', c.W.CANVAS_LIMIT, 0);
        c.game.updateDrawing();
        missReset(c);
        c.clickAt(c.W.CANVAS_LIMIT + 35, 0);
        await c.tick();
        said.toolarge = toastText(c);
        assert(c.game.userMolecule.atoms.length === 1, 'キャンバス上限のクリックで原子が増えた');

        Object.entries(said).forEach(([k, v]) => {
            assert(v && v.length > 0, `${k} で字幕が出ない（クリックが黙って捨てられている）`);
        });
        const uniq = new Set(Object.values(said));
        assert(uniq.size === 4,
            `4通りが言い分けられていない（出た文言 ${uniq.size} 種類）: ${JSON.stringify(said)}`);
        assert(said.crowded.includes('近すぎ') && said.crowded.includes('新しい分子'),
            `自由配置の近すぎの文言が違う: ${said.crowded}`);
        assert(said.overlap.includes('近すぎ'), `近すぎの文言が違う: ${said.overlap}`);
        assert(said.blocked.includes('空き'), `空きなしの文言が違う: ${said.blocked}`);
        assert(said.toolarge.includes('5000'), `キャンバス上限の文言が違う: ${said.toolarge}`);
    });

    test('PW2: 「近くの別の原子に取られた」を名指しできる（環→鎖→先端に枝）', async (c) => {
        c.reset();
        c.game.selectedModule = 'cyclohexane';
        c.game.placeModule('cyclohexane', 400, 300, null, null);
        c.game.selectedModule = null;
        const ring = c.game.userMolecule.atoms.filter(a => a.element === 'C');
        const R = ring.reduce((b, a) => (a.x > b.x ? a : b), ring[0]);
        const sc = c.game.getSnappedCoords(c.toClient(R.x + 35, R.y));
        const T = c.game.userMolecule.addAtom('C', sc.x, sc.y);
        c.game.userMolecule.addBond(R.id, T.id, 1);
        // R の「側鎖2本目」の候補点を、空き価標0の O 三角形でふさぐ
        const bp = c.game.secondBranchPoints(R);
        assert(bp.length > 0, '側鎖2本目の候補点が無い（場面の作り方が古い）');
        bp.forEach(p => {
            const o1 = c.game.userMolecule.addAtom('O', p.x, p.y);
            const o2 = c.game.userMolecule.addAtom('O', p.x - 18, p.y - 10);
            const o3 = c.game.userMolecule.addAtom('O', p.x - 18, p.y + 10);
            c.game.userMolecule.addBond(o1.id, o2.id, 1);
            c.game.userMolecule.addBond(o2.id, o3.id, 1);
            c.game.userMolecule.addBond(o3.id, o1.id, 1);
        });
        c.game.updateDrawing();
        missReset(c);
        const spot = findMissSpot(c, T.x, T.y, { stolen: true });
        assert(spot, '「取られた」失敗になる点が作れなかった');
        assert(spot.coords.blockedAtom && spot.coords.blockedAtom.id === R.id,
            '取った相手が環炭素 R になっていない');
        c.clickAt(spot.x, spot.y);
        await c.tick();
        const msg = toastText(c);
        assert(msg.includes('取られました'), `取られた旨が字幕に出ない: ${msg}`);
        // 図でも名指しする（言葉では原子に名前が無いので指せない）
        const marks = c.D.getElementById('miss-group').querySelectorAll('circle');
        assert(marks.length >= 2,
            `押した点と「取った原子」の2つに丸が付かない（丸は ${marks.length} 個）`);
    });

    test('PW3: 失敗が連続してもうるさくしない（同じ理由は出し直さない）', async (c) => {
        // v1130: 連打の誘発は「遠すぎ」から「近すぎ（自由配置）」の場面に差し替えた
        // （遠すぎは自由配置になり、失敗しなくなったため）
        const spot = crowdedScene(c);
        missReset(c);
        const toast = c.D.getElementById('canvas-toast');
        let changes = 0;
        let last = toast.textContent;
        const obs = new c.W.MutationObserver(() => {
            if (toast.textContent !== last) { last = toast.textContent; changes++; }
        });
        obs.observe(toast, { childList: true, characterData: true, subtree: true });
        for (let i = 0; i < 12; i++) {
            c.clickAt(spot.x, spot.y);
            await c.tick(20);
        }
        await c.tick(30);
        obs.disconnect();
        assert(changes === 1, `同じ理由を12連打して字幕が ${changes} 回書き換わった（1回が正）`);
        assert(c.D.getElementById('miss-group').children.length <= 1,
            '押した点のしるしが積み重なっている');

        // 理由が入れ替わっても、直前の文言が出たばかりなら差し替えない（読む前に消えない）
        const crowd = crowdedScene(c, 800, 300);
        c.game.userMolecule.addAtom('C', 400, 300);
        wallCO2(c, 380, 240, 42, 0);
        wallCO2(c, 400, 196, 42, 0);
        c.game.updateDrawing();
        missReset(c);
        const near2 = findMissSpot(c, 400, 300, { reason: 'overlap' });
        assert(near2, '「近すぎ」になる点が作れなかった');
        c.clickAt(crowd.x, crowd.y);    // 近すぎ（自由配置）
        await c.tick(20);
        const t1 = toastText(c);
        assert(t1.includes('新しい分子'), `1つめの理由が自由配置の近すぎでない: ${t1}`);
        c.clickAt(near2.x, near2.y);    // 近すぎ（延長で詰む・すぐ）
        await c.tick(20);
        assert(toastText(c) === t1,
            `理由が変わった直後に字幕が差し替わった（ちらつく）: ${toastText(c)}`);
        await c.tick(900);
        c.clickAt(near2.x, near2.y);    // 近すぎ（900ms 後）
        await c.tick(20);
        assert(toastText(c) !== t1 && toastText(c).includes('結合線をドラッグ'),
            `時間をおいても理由が更新されない: ${toastText(c)}`);
    });

    test('PW4: 押した点のしるしは pointermove で消えず、置けたら消える', async (c) => {
        // v1130: 失敗の作り方を「遠すぎ」から「近すぎ（自由配置）」に差し替えた（PW3 と同じ理由）
        const spot = crowdedScene(c, 800, 300);
        c.game.userMolecule.addAtom('C', 400, 300);
        c.game.updateDrawing();
        missReset(c);
        const missG = c.D.getElementById('miss-group');
        assert(missG, 'miss-group が無い（ui-group と分けた専用グループ）');
        const before = c.game.userMolecule.atoms.filter(a => a.element !== 'H').length;
        c.clickAt(spot.x, spot.y);
        await c.tick();
        assert(missG.children.length === 1, '押した点のしるしが出ない');
        // ui-group は pointermove のたびに空にされる。しるしはそこに描いてはいけない
        c.hoverAt(500, 500);
        await c.tick();
        assert(missG.children.length === 1,
            'pointermove でしるしが消えた（ui-group に描いてしまっている）');
        // 置けたら消える（成功したのに「外した」しるしが残らない）
        c.clickAt(442, 300);
        await c.tick();
        assert(missG.children.length === 0, '置けたのに「外した」しるしが残っている');
        assert(c.game.userMolecule.atoms.filter(a => a.element !== 'H').length === before + 1,
            '置けるはずのクリックで原子が増えていない');
    });

    test('PW5: ベンゼンの置換基が となりと重なる分岐でも黙って捨てない', async (c) => {
        c.reset();
        c.game.selectedModule = 'benzene';
        c.game.placeModule('benzene', 400, 300, null, null);
        c.game.selectedModule = null;
        const bz = c.game.userMolecule.atoms.filter(a => a.element === 'C');
        const right = bz.reduce((b, a) => (a.x > b.x ? a : b), bz[0]);
        // 置換基が出る点（頂点から外へ 27.97px）のすぐ脇に別分子を置いて塞ぐ。
        // ⚠ 塞ぐ相手は**空き価標0の壁**にする（v1130）。空き価標があると吸着の候補に混ざり、
        //    「取られました」の場面（PW2 の担当）になってしまってここの文言が変わる
        const px = right.x + 27.97 * Math.cos(right.benzeneAngle);
        const py = right.y + 27.97 * Math.sin(right.benzeneAngle);
        wallCO2(c, px, py + 27, 42, 0);
        c.game.updateDrawing();
        missReset(c);
        const spot = findMissSpot(c, right.x, right.y, { reason: 'overlap', stolen: false });
        assert(spot, 'ベンゼンの置換基が塞がる点が作れなかった');
        const before = c.game.userMolecule.atoms.length;
        c.clickAt(spot.x, spot.y);
        await c.tick();
        assert(c.game.userMolecule.atoms.length === before, '塞がっているのに原子が増えた');
        assert(toastText(c).includes('近すぎ'),
            `ベンゼンの置換基の重なりが黙って捨てられている: 「${toastText(c)}」`);
    });

    // ===== HA. 作図の当たり判定（v1130・DESIGN_hit_areas.md） =====
    //
    // タップの意味を「最寄り原子までの距離 d」の3帯で決める:
    //   d ≤ 18（ATOM_TAP_RADIUS）… その原子への操作（削除・元素置換）
    //   d ≤ 63（SNAP_RADIUS = GRID_SIZE*1.5）… 隣に足す（吸着）
    //   それ以上 … 自由配置（新しい分子を始める）
    // 吸着先は「**新しい原子が実際に出る位置**が指にいちばん近い原子」が勝つ。
    //
    // **HA6〜HA9 は否定対照**（直しを外すと赤くなることの証明）。
    // 「直したつもりで何も検査していない」を避けるため、テスト側で幾何を書き写すのではなく
    // `HIT_AREAS` のつまみを旧値に戻して**本番の経路をそのまま旧挙動で走らせる**。

    // つまみを一時的に差し替える（必ず戻す）
    const withHit = (c, patch, fn) => {
        const H = c.W.HIT_AREAS;
        const saved = Object.assign({}, H);
        Object.assign(H, patch);
        try { return fn(); } finally { Object.assign(H, saved); }
    };
    const heavyOf = (c) => c.game.userMolecule.atoms.filter(a => a.element !== 'H');
    // クリックして「何が起きたか」を返す（増えた重原子 / 減った）
    const tapResult = (c, x, y) => {
        const before = heavyOf(c).map(a => a.id);
        c.clickAt(x, y);
        const after = heavyOf(c);
        if (after.length < before.length) return { deleted: true, added: null };
        return { deleted: false, added: after.find(a => !before.includes(a.id)) || null };
    };
    // 直鎖の先端（(400,300)。手前に (358,300) がある）
    const chainScene = (c) => {
        c.reset();
        const a = c.game.userMolecule.addAtom('C', 358, 300);
        const b = c.game.userMolecule.addAtom('C', 400, 300);
        c.game.userMolecule.addBond(a.id, b.id, 1);
        c.game.updateDrawing();
        return b;
    };
    // 先端から d px 右をタップして、先端に結合した原子が 42px 先に出たか
    const extendOk = (c, d) => {
        const tip = chainScene(c);
        const r = tapResult(c, tip.x + d, tip.y);
        return !!(r.added && c.game.userMolecule.getBond(tip.id, r.added.id) &&
                  Math.abs(r.added.x - (tip.x + 42)) < 2 && Math.abs(r.added.y - tip.y) < 2);
    };
    // 環 → 鎖 → その先端（発注書 2d の場面）
    const ringChainScene = (c) => {
        c.reset();
        c.game.placeModule('cyclohexane', 400, 300, null, null);
        const ring = heavyOf(c);
        const R = ring.reduce((b, a) => (a.x > b.x ? a : b), ring[0]);
        const sc = c.game.getSnappedCoords(c.toClient(R.x + 35, R.y));
        const T = c.game.userMolecule.addAtom('C', sc.x, sc.y);
        c.game.userMolecule.addBond(R.id, T.id, 1);
        c.game.updateDrawing();
        return { R, T };
    };
    const DIRS = { '→': [1, 0], '↓': [0, 1], '↑': [0, -1], '↘': [0.7071, 0.7071], '↗': [0.7071, -0.7071] };
    // 先端から d px 離してタップしたとき、**先端に**枝が付いた方位
    const tipDirections = (c, d) => Object.entries(DIRS).filter(([, [ux, uy]]) => {
        const { T } = ringChainScene(c);
        const r = tapResult(c, T.x + ux * d, T.y + uy * d);
        return !!(r.added && c.game.userMolecule.getBond(T.id, r.added.id));
    }).map(([k]) => k);
    // メチルシクロヘキサンの2本目（P12-8）。二等分線±30°の点をタップして誰が勝つか
    const secondBranchWinner = (c) => {
        c.reset();
        c.game.placeModule('cyclohexane', 400, 300, null, null);
        const ring = heavyOf(c);
        const top = ring.reduce((b, a) => (a.y < b.y ? a : b), ring[0]);
        const c1 = c.game.getSnappedCoords(c.toClient(top.x, top.y - 42));
        const me = c.game.userMolecule.addAtom('C', c1.x, c1.y);
        c.game.userMolecule.addBond(top.id, me.id, 1);
        c.game.updateDrawing();
        const bp = c.game.secondBranchPoints(top);
        assert(bp.length === 2, '側鎖2本目の候補点が無い（場面の作り方が古い）');
        // ⚠ 距離はタップの**前**に測る。置いた瞬間に既存の側鎖が反対側へ振り分けられる（P6-3）ので、
        //    あとで測ると移動後の位置（42px）になる
        const gap = Math.hypot(me.x - bp[0].x, me.y - bp[0].y);
        const r = tapResult(c, bp[0].x, bp[0].y);
        if (!r.added) return { winner: r.deleted ? 'deleted' : 'none', gap };
        if (c.game.userMolecule.getBond(top.id, r.added.id)) return { winner: 'ring', gap };
        if (c.game.userMolecule.getBond(me.id, r.added.id)) return { winner: 'methyl', gap };
        return { winner: 'other', gap };
    };
    // ベンゼンから d px 離した所に五員環を「別の分子として」置けるか
    const freeRingOk = (c, d) => {
        c.reset();
        c.game.placeModule('benzene', 400, 300, null, null);
        const bz = heavyOf(c);
        const right = bz.reduce((b, a) => (a.x > b.x ? a : b), bz[0]);
        const before = heavyOf(c).length;
        c.game.selectedModule = 'cyclopentane';
        c.game.placeModule('cyclopentane', right.x + d, right.y, null, null);
        c.game.selectedModule = null;
        return heavyOf(c).length === before + 5 && c.game.countMolecules() === 2;
    };

    test('HA1: 鎖の延長は「置き先の近く」ならどこでも届く（吸着半径 63px）', async (c) => {
        // 置きたい点は先端の 42px 先。もとは吸着半径 45px ＝ **的の外周 3px** を狙う操作で、
        // 成功する帯は 30〜44px しかなかった（実測。46px で×）
        [20, 26, 32, 42, 50, 63].forEach(d => {
            assert(extendOk(c, d), `先端から ${d}px のタップで鎖が伸びない`);
        });
        // 吸着半径そのものの検査: **置き先(42px)から 55px 離れた点**でも、その置き先に置ける。
        // ここが SNAP_RADIUS が効いている場所（45 に戻すと届かない ＝ 否定対照 HA6）
        assert(extendOk(c, 42 + 55), '置き先から 55px 離れたタップが吸着しない（SNAP_RADIUS が狭い）');
        // 遠すぎる側は自由配置（別の分子）になる。黙って捨てられてはいけない
        const tip = chainScene(c);
        const r = tapResult(c, tip.x + 300, tip.y);
        assert(r.added && !c.game.userMolecule.getBond(tip.id, r.added.id),
            '遠い場所のタップが自由配置にならない');
    });

    test('HA2: 環→鎖→その先端に枝が付く（5方位中4方位以上）', async (c) => {
        const ok = tipDirections(c, 42);
        assert(ok.length >= 4,
            `先端に枝が付く方位が ${ok.length}/5 しかない（合格ラインは 4）: ${ok.join('')}`);
        // 帯の幅も見る（1点だけ通る細い的では意味がない）
        const wide = tipDirections(c, 30);
        assert(wide.length >= 4,
            `30px でも 4方位に届かない（${wide.length}/5）: ${wide.join('')}`);
    });

    test('HA3: 「足すつもりで削除」が起きない（破壊操作は原子の上だけ）', async (c) => {
        // 発注書 2d の事故。20〜26px を押すと足すつもりが**先端の原子が消えた**（実際に4回踏んだ）
        [20, 24, 28].forEach(d => {
            const { T } = ringChainScene(c);
            const r = tapResult(c, T.x + d, T.y);
            assert(!r.deleted, `先端から ${d}px のタップで原子が消えた（足す帯のはず）`);
            assert(r.added, `先端から ${d}px のタップで何も起きない`);
        });
        // 削除そのものは残っている（グリフの上をタップすれば消える）
        const { T } = ringChainScene(c);
        const r = tapResult(c, T.x, T.y);
        assert(r.deleted, '原子の上をタップしても削除にならない（消す手段が消えた）');
    });

    test('HA4: 空いている所には自由に置ける（単原子・環モジュール）', async (c) => {
        // 単原子
        c.reset();
        c.game.userMolecule.addAtom('C', 400, 300);
        c.game.updateDrawing();
        const r = tapResult(c, 700, 500);
        assert(r.added, '離れた場所に単原子を置けない');
        assert(c.game.countMolecules() === 2, '別の分子として置かれていない');
        assert(r.added.x % c.W.GRID_SIZE === 0 && r.added.y % c.W.GRID_SIZE === 0,
            `自由配置がグリッドに乗っていない (${r.added.x}, ${r.added.y})`);
        // 環モジュール（もとは 72〜112px の帯でしか置けなかった ＝ ニコチンが組めない原因）。
        // クリアランス（27.3px）で弾かれる 70px までは従来どおり不可、**その先はぜんぶ可**
        assert(!freeRingOk(c, 70), '重なる近さ（70px）でも置けてしまう（クリアランスが効いていない）');
        [72, 120, 200, 400].forEach(d => {
            assert(freeRingOk(c, d), `ベンゼンから ${d}px 離した所に五員環を置けない`);
        });
    });

    test('HA5: メチルシクロヘキサンの2本目は環炭素が勝つ（P12-8 の維持）', async (c) => {
        const { winner, gap } = secondBranchWinner(c);
        assert(winner === 'ring',
            `側鎖2本目の吸着先が環炭素でない（${winner}）＝ P12-8 の退行`);
        // なぜ素朴な「最寄り原子が勝つ」を採れないかの数字（DESIGN §1-E）:
        // 2本目の出現位置は既存メチル炭素から 2·42·sin15° ≈ 21.7px しか離れていない
        assert(Math.abs(gap - 21.7) < 1.5,
            `2本目の出現位置とメチル炭素の距離が想定と違う（${gap.toFixed(1)}px・想定 21.7px）`);
        assert(gap > c.W.ATOM_TAP_RADIUS,
            `2本目の点が削除の帯（${c.W.ATOM_TAP_RADIUS}px）に入っている`);
    });

    test('HA6: 否定対照 —— 吸着半径を 45 に戻すと HA1 が届かなくなる', async (c) => {
        const ok = withHit(c, { snapRadius: 45 }, () => extendOk(c, 42 + 55));
        assert(!ok, '吸着半径を 45 に戻しても届く ＝ HA1 は空振りの緑');
    });

    test('HA7: 否定対照 —— 勝敗則を旧式に戻すと HA2 が赤（P12-8 は両方で緑）', async (c) => {
        const ok = withHit(c, { legacyWinner: true }, () => tipDirections(c, 42));
        assert(ok.length < 4,
            `旧式（候補点込みの最短）でも ${ok.length}/5 方位に付く ＝ HA2 は空振りの緑`);
        // **両立の証明**: 旧式でも P12-8 は通る（新旧の差は 2d だけで、P12-8 を犠牲にしていない）
        const old = withHit(c, { legacyWinner: true }, () => secondBranchWinner(c));
        assert(old.winner === 'ring',
            `旧式で P12-8 が通らない（${old.winner}）＝ 場面の作り方が古い`);
    });

    test('HA8: 否定対照 —— 破壊操作の半径を 28 に戻すと「足すつもりで削除」が戻る', async (c) => {
        const deleted = withHit(c, { atomTapRadius: 28 }, () => {
            const { T } = ringChainScene(c);
            return tapResult(c, T.x + 24, T.y).deleted;
        });
        assert(deleted, '28px に戻しても原子が消えない ＝ HA3 は空振りの緑');
    });

    test('HA9: 否定対照 —— 孤立禁止則を復活させると環を自由に置けなくなる', async (c) => {
        const ok = withHit(c, { legacyIsolation: true }, () => freeRingOk(c, 200));
        assert(!ok, '孤立禁止則を戻しても置ける ＝ HA4 は空振りの緑');
    });

    // ===== GR. 絶対グリッドへの丸め（要望G ＝「収録レイアウトだと 42px ずれる」・v1150）=====
    //
    // client 座標 → 論理座標 は `getScreenCTM()` の**逆行列**を通るので、戻り値に 1e-13 級の
    // 誤差が乗る。しかも誤差の向きは**行列の中身 ＝ 画面レイアウト**で変わる。
    // ちょうど半格子（42 の倍数 ±21）を狙うと、その誤差が Math.round の分かれ目のうえに乗り、
    // **同じ台本の同じタップが 42px 違う所へ落ちる**。実測（810×1440・台本 V85 の y=273）:
    //     ?mode=free  論理 y = 273                  → round(6.5)                = 7 → 294
    //     ?rec=       論理 y = 272.99999999999994   → round(6.499999999999998) = 6 → 252
    // （?rec= はヘッダーを隠すので SVG の上端が 110px → 66px へ動く ＝ CTM の平行移動が変わる）
    // V85（ニコチン）が下見では C₁₀H₁₄N₂、収録では C₉H₁₄N₂ になった原因。
    //
    // 検査は**誤差そのものを注いで**行う。実測の食い違いは 5.7e-14 だが、テストは桁を大きくして
    // 1e-10 を注ぐ ＝ **検査環境の CTM がたまたまどちら側にぶれていても、両符号のどちらかは
    // 必ず分かれ目をまたぐ**（1e-10 論理px は図の 0.1pm 相当。目にも操作にも意味が無い量で
    // 落ち先が 42px 動く、という不具合の形は変わらない）。
    const CTM_NOISE = 1e-10;

    // clientToSvg の戻り値に誤差を足して（＝別レイアウトを模して）fn を走らせる
    const withCtmNoise = (c, sign, fn) => {
        const g = c.game;
        const orig = g.clientToSvg;
        g.clientToSvg = function (cx, cy) {
            const p = orig.call(this, cx, cy);
            return p ? { x: p.x + sign * CTM_NOISE, y: p.y + sign * CTM_NOISE } : p;
        };
        try { return fn(); } finally { g.clientToSvg = orig; }
    };

    // 半格子の点 (546,273) をタップして、落ちた重原子をそろえて返す。
    // module を渡すと環／ハース環モジュールの配置経路、null なら単原子の経路になる
    const halfGridDrop = (c, module) => {
        c.reset();
        c.game.selectedModule = module;
        c.clickAt(546, 273);
        c.game.selectedModule = null;
        return heavyOf(c).map(a => `${a.element}(${Math.round(a.x)},${Math.round(a.y)})`)
            .sort().join(' ');
    };
    const GR_PATHS = [
        { module: null, label: '単原子' },
        { module: 'cyclopentane', label: '環モジュール' },
        { module: 'haworth-pyranose', label: 'ハース環' }
    ];

    test('GR1: 半格子を狙っても丸め先が誤差で反転しない（snapToGrid）', async (c) => {
        const S = c.W.snapToGrid;
        assert(typeof S === 'function', 'snapToGrid が公開されていない');
        // 42 の倍数 ±21 ＝ 丸めの分かれ目。CTM 逆変換の誤差で向きが変わってはいけない
        [21, 63, 231, 273, 525, -21, -273].forEach(v => {
            const base = S(v);
            [5.7e-14, -5.7e-14, 1e-10, -1e-10, 4e-7, -4e-7].forEach(e => {
                assert(S(v + e) === base,
                    `半格子 ${v} が ${e} の誤差で ${S(v + e)} と ${base} に割れる`);
            });
        });
        // 丸めそのものは変えていない（最寄りの格子・半格子は上side＝Math.round の慣習どおり）
        assert(S(546) === 546 && S(0) === 0 && S(100) === 84 && S(200) === 210 && S(273) === 294,
            'グリッド丸めそのものが壊れている');
    });

    test('GR2: 半格子のタップは画面レイアウトが変わっても同じ所に落ちる（3経路）', async (c) => {
        GR_PATHS.forEach(({ module, label }) => {
            const clean = halfGridDrop(c, module);
            assert(clean.length > 0, `${label}: 半格子のタップで何も置かれない（場面の作り方が古い）`);
            [1, -1].forEach(sign => {
                const noisy = withCtmNoise(c, sign, () => halfGridDrop(c, module));
                assert(noisy === clean,
                    `${label}: ${sign > 0 ? '+' : '−'}1e-10 の誤差で落ち先が動く\n  素 : ${clean}\n  誤差: ${noisy}`);
            });
        });
    });

    test('GR3: 否定対照 —— 素の Math.round に戻すと 42px ずれが戻る', async (c) => {
        const shifted = GR_PATHS.filter(({ module }) => withHit(c, { legacyGridRound: true }, () => {
            const clean = halfGridDrop(c, module);
            return [1, -1].some(sign =>
                withCtmNoise(c, sign, () => halfGridDrop(c, module)) !== clean);
        }));
        assert(shifted.length === GR_PATHS.length,
            `旧式に戻しても ${GR_PATHS.length - shifted.length} 経路がずれない ＝ GR2 は空振りの緑`);
    });

    // ===== BX. 伸長した結合線が既存の原子の下をくぐらない（発注書 §2g・v1160）=====
    //
    // **原子どうしの距離だけを見ていた穴。** 置き場が詰まると結合は 42→84px まで延ばして
    // 逃がすが、**延ばした線が既存の原子の下を通るか**は誰も見ていなかった。
    // 同じ検査は反応実行（reactor.js の strict）と整形モード（_hasBondThroughAtom）には
    // 前からあり、**手描きの配置だけ無かった**。
    //
    // ⚠ **総当たりでは出ない**（側鎖3通り × 全周24方向 × 距離3通り ≒ 600通りで0件）。
    // **伸長が起きる詰まった場所**でだけ出るので、場面は手順で組む。

    // その分子の「重原子 ↔ その原子を端点に持たない結合線」の最短距離。
    // アプリ側の判定（atomUnderBondLine）とは独立に、テスト自身の物差しで測る
    // （＝アプリの式が変わっても、この数字は素直に px を返す）
    const minAtomBondGap = (c, mol) => {
        const byId = new Map(mol.atoms.map(a => [a.id, a]));
        let worst = Infinity, detail = '';
        mol.bonds.forEach(b => {
            const p = byId.get(b.atomId1), q = byId.get(b.atomId2);
            if (!p || !q || p.element === 'H' || q.element === 'H') return;
            const L2 = (q.x - p.x) ** 2 + (q.y - p.y) ** 2;
            if (!L2) return;
            mol.atoms.forEach(a => {
                if (a.element === 'H' || a.id === p.id || a.id === q.id) return;
                const t = ((a.x - p.x) * (q.x - p.x) + (a.y - p.y) * (q.y - p.y)) / L2;
                if (t <= 0.02 || t >= 0.98) return; // 端点のそばは原子どうしの間隔の領分
                const d = Math.hypot(a.x - (p.x + t * (q.x - p.x)), a.y - (p.y + t * (q.y - p.y)));
                if (d < worst) {
                    worst = d;
                    detail = `${a.element}(${a.x.toFixed(0)},${a.y.toFixed(0)}) ↔ ` +
                        `${p.element}(${p.x.toFixed(0)},${p.y.toFixed(0)})-${q.element}(${q.x.toFixed(0)},${q.y.toFixed(0)})`;
                }
            });
        });
        return { gap: worst, detail };
    };

    // 発注書 §2g の手順そのまま:
    //   ① シクロヘキサン ② 環炭素(456,273) にメチル ③ そのメチルから**下へ**エチル
    //   ④ **同じ環炭素**に右向きでもう1本
    // ④ で結合が 42→48.3px に延び、その線から 5.6px の所に③の炭素が来ていた
    const crowdedSecondBranch = (c) => {
        c.reset();
        c.game.selectedModule = 'cyclohexane';
        c.game.placeModule('cyclohexane', 420, 294, null, null);
        c.game.selectedModule = null;
        const ring = heavyOf(c).find(a => Math.abs(a.x - 456.4) < 2 && Math.abs(a.y - 273) < 2);
        c.clickAt(492, 252);                                   // ② メチル
        const tip = heavyOf(c).reduce((b, a) => (a.x > b.x ? a : b));
        c.clickAt(tip.x, tip.y + 42);                          // ③ 下へエチル
        const preview = c.game.getSnappedCoords(c.toClient(ring.x + 42, ring.y));
        c.clickAt(ring.x + 42, ring.y);                        // ④ 同じ環炭素に右向き
        return { preview, ...minAtomBondGap(c, c.game.userMolecule) };
    };

    test('BX1: 詰まった場所へ足しても、伸ばした結合線が原子の下をくぐらない', async (c) => {
        const r = crowdedSecondBranch(c);
        assert(r.preview.isValid, `④ が置けない（reason=${r.preview.reason}）＝ 場面の作り方が古い`);
        assert(heavyOf(c).length === 9, `重原子が ${heavyOf(c).length} 個（環6＋側鎖3を期待）`);
        // 素の格子で起こりうる最小は 21px（= 42·sin30°）。しきい値はその明確に下
        assert(r.gap >= c.W.BOND_ATOM_CLEARANCE,
            `結合線の下に原子が来た（${r.gap.toFixed(1)}px < ${c.W.BOND_ATOM_CLEARANCE}px）: ${r.detail}`);
    });

    test('BX2: 名称ライブラリの全図が「結合線の下の原子」を持たない（登録図の再現性）', async (c) => {
        c.reset();
        const bad = [];
        let worst = { gap: Infinity, name: '', detail: '' };
        withoutRendering(c, () => {
            c.W.COMPOUNDS.forEach(entry => {
                c.game.userMolecule = new c.W.Molecule();
                c.game.summonMolecule(entry.name);
                const r = minAtomBondGap(c, c.game.userMolecule);
                if (r.gap < worst.gap) worst = { ...r, name: entry.name };
                if (r.gap < c.W.BOND_ATOM_CLEARANCE) bad.push(`${entry.name} ${r.gap.toFixed(1)}px`);
            });
        });
        c.game.userMolecule = new c.W.Molecule();
        assert(c.W.COMPOUNDS.length >= 900, `母数が ${c.W.COMPOUNDS.length} 件（900件以上を期待）`);
        assert(bad.length === 0, `登録図が新しい物差しで弾かれる: ${bad.slice(0, 5).join(' / ')}`);
        // 実測の最小は 25.99px（糖のハース環）。しきい値 16px には十分な余裕がある
        assert(worst.gap > 20,
            `登録図の最小が ${worst.gap.toFixed(1)}px（${worst.name}）＝ しきい値に余裕が無い`);
        assertRenderingRestored(c);
    });

    test('BX3: 否定対照 —— くぐり検査を外すと 5.6px の食い込みが戻る', async (c) => {
        // ⚠ **v1240 から、外すつまみは2つ要る。** 自動水素のくぐり門番（HX）が入り、
        //    §2g のこの場面では **H の門番も同じ 48.3px の置き方を独立に断る**ようになった。
        //    `legacyBondCross` だけを外すと 18.2px までしか戻らない ―― つまり
        //    「BX1 が緑なのは BX の門番のおかげ」とは、もう単独では言えない。
        //    そこを隠さず、**2つ外した状態＝ v1160 より前の挙動**で食い込みが戻ることを見る。
        const both = withHit(c, { legacyBondCross: true, legacyHydrogenCross: true },
            () => crowdedSecondBranch(c));
        assert(both.gap < 10,
            `2つとも外しても ${both.gap.toFixed(1)}px しか詰まらない ＝ BX1 は空振りの緑`);
        // 記録として、H の門番だけでもこの場面が守られていることも見ておく
        const heavyOnly = withHit(c, { legacyBondCross: true }, () => crowdedSecondBranch(c));
        assert(heavyOnly.gap >= c.W.BOND_ATOM_CLEARANCE,
            `H の門番だけでは §2g の場面が守れていない（${heavyOnly.gap.toFixed(1)}px）`);
    });

    test('BX4: どうしても避けられないときは「くぐる」専用の理由を字幕に出す', async (c) => {
        // 通り道のまんなかに、結合線から 12px だけ横にずれた原子を置く。
        // 42〜84px のどこへ延ばしても **perpendicular 12px は変わらない** ＝ 伸ばす逃げ道が無い
        c.reset();
        const a = c.game.userMolecule.addAtom('C', 400, 300);
        c.game.userMolecule.addAtom('C', 442, 288);
        c.game.updateDrawing();
        missReset(c);
        const spot = findMissSpot(c, a.x, a.y, { reason: 'crossing' });
        assert(spot, '「くぐる」で止まる点が作れなかった（場面の作り方が古い）');
        const before = c.game.userMolecule.atoms.length;
        c.clickAt(spot.x, spot.y);
        await c.tick();
        const msg = toastText(c);
        assert(c.game.userMolecule.atoms.length === before, 'くぐるクリックで原子が増えた');
        assert(msg.includes('別の原子の上を通'), `くぐりの文言が違う: ${msg}`);
        // 'overlap'（伸ばせば空く）と**言い分ける**。同じ文言なら手当てを誤らせる
        assert(!msg.includes('結合線をドラッグして伸ばす'),
            `くぐりなのに「伸ばせば空く」と案内している: ${msg}`);
    });

    // ===== HX. 伸長した結合線が「自動水素」の下をくぐらない（§10-7 の決着・v1240）=====
    //
    // **BX が塞いだのは重原子だけだった。** 自動水素は `userMolecule.atoms` に入っておらず
    // **描かれているだけ**なので、BX の門番も `MIN_CLEARANCE` も H を1つも見ていない。
    // 伸ばした結合線が、別の原子から生えた H のグリフ（半径6px）の上を通っても誰も止めなかった。
    //
    // しきい値は **12px**（重原子の 16px とは**別に持つ**。H の絵が小さいぶん実害が出る距離も近い。
    // 白場を 6px 残す、という決め方は重原子とそろえてある）。
    // 実測: 登録図 939件のまわり 125,856 通りを叩くと、置けた 116,872 通りのうち
    // **719 通り**でくぐり（最悪 0.0px ＝ H の中心が線の上）。直したあとは **0 通り**。
    //
    // ⚠ 測るのは `calculateHydrogens()` の出しなおし ―― H の向きは分子ぜんたいの形で決まる
    //   （75px 以内の非結合原子を ±60° 避ける）ので、置く前の H からは推せない。

    // 「H ↔ その H の親を端点に持たない結合線」の最短距離。
    // BX の `minAtomBondGap` と同じで、**アプリの判定とは独立に**素の px を返す
    const minHydrogenBondGap = (c, mol) => {
        const hs = mol.calculateHydrogens();
        const byId = new Map(mol.atoms.map(a => [a.id, a]));
        let worst = Infinity, detail = '';
        mol.bonds.forEach(b => {
            const p = byId.get(b.atomId1), q = byId.get(b.atomId2);
            if (!p || !q || p.element === 'H' || q.element === 'H') return;
            hs.forEach(h => {
                if (h.parentId === p.id || h.parentId === q.id) return;
                const d = c.W.pointSegmentDistance(h, p, q);
                if (d < worst) {
                    worst = d;
                    detail = `H(${h.x.toFixed(0)},${h.y.toFixed(0)}) ↔ ` +
                        `${p.element}(${p.x.toFixed(0)},${p.y.toFixed(0)})-${q.element}(${q.x.toFixed(0)},${q.y.toFixed(0)})`;
                }
            });
        });
        return { gap: worst, detail };
    };

    // 場面: シス-2-ブテン（±120° に開いた C=C。メチルが2つとも上）。
    // 左の二重結合炭素の**メチル側**へもう1本足すと、42→55px に延びた結合線が
    // 左のメチルから生えた H（16px 先）の上を通っていた ―― 実測 **9.5px**
    // （新しい結合 (400,300)-(400,245) と H(391,264)）。
    // 原子どうしは 27.3px 以上あいているので、**BX の門番では1件も出ない壊れ方**
    const cisButeneBranch = (c) => {
        c.reset();
        const m = c.game.userMolecule;
        const a = m.addAtom('C', 400, 300), b = m.addAtom('C', 442, 300);
        const ma = m.addAtom('C', 379, 263.6), mb = m.addAtom('C', 463, 263.6);
        m.addBond(a.id, b.id, 2);
        m.addBond(a.id, ma.id, 1);
        m.addBond(b.id, mb.id, 1);
        c.game.updateDrawing();
        const before = heavyOf(c).length;
        c.clickAt(395, 240);
        return { added: heavyOf(c).length - before, ...minHydrogenBondGap(c, c.game.userMolecule) };
    };

    test('HX1: 詰まった場所へ足しても、伸ばした結合線が自動水素の下をくぐらない', async (c) => {
        const r = cisButeneBranch(c);
        assert(r.added === 1, `原子が ${r.added} 個増えた（1個を期待）＝ 場面の作り方が古い`);
        assert(r.gap >= c.W.HYDROGEN_BOND_CLEARANCE,
            `結合線の下に自動水素が来た（${r.gap.toFixed(1)}px < ${c.W.HYDROGEN_BOND_CLEARANCE}px）: ${r.detail}`);
    });

    test('HX2: 名称ライブラリの全図が「結合線の下の自動水素」を持たない（登録図の再現性）', async (c) => {
        c.reset();
        const bad = [];
        let worst = { gap: Infinity, name: '', detail: '' };
        withoutRendering(c, () => {
            c.W.COMPOUNDS.forEach(entry => {
                c.game.userMolecule = new c.W.Molecule();
                c.game.summonMolecule(entry.name);
                const r = minHydrogenBondGap(c, c.game.userMolecule);
                if (r.gap < worst.gap) worst = { ...r, name: entry.name };
                if (r.gap < c.W.HYDROGEN_BOND_CLEARANCE) bad.push(`${entry.name} ${r.gap.toFixed(1)}px`);
            });
        });
        c.game.userMolecule = new c.W.Molecule();
        assert(c.W.COMPOUNDS.length >= 900, `母数が ${c.W.COMPOUNDS.length} 件（900件以上を期待）`);
        assert(bad.length === 0, `登録図が新しい物差しで弾かれる: ${bad.slice(0, 5).join(' / ')}`);
        // 実測の最小は 14.32px（スクロース・β-D-フルクトフラノース）。14px 未満は0件。
        // しきい値 12px には 2.3px の余裕がある ―― ここが 12 に迫ったら、
        // **しきい値ではなく登録図のほうを直す**（12 は白場 6px の下限）
        assert(worst.gap > 13,
            `登録図の最小が ${worst.gap.toFixed(1)}px（${worst.name}）＝ しきい値に余裕が無い`);
        assertRenderingRestored(c);
    });

    test('HX3: 否定対照 —— 自動水素の検査を外すと 9.5px の食い込みが戻る', async (c) => {
        const r = withHit(c, { legacyHydrogenCross: true }, () => cisButeneBranch(c));
        assert(r.added === 1, `旧挙動で原子が ${r.added} 個増えた（1個を期待）`);
        assert(r.gap < 12,
            `検査を外しても ${r.gap.toFixed(1)}px しか詰まらない ＝ HX1 は空振りの緑: ${r.detail}`);
    });

    test('HX4: 自由配置（新しい分子として置く）でも、その原子の H が結合線に乗るなら止める', async (c) => {
        // **吸着と自由配置は別の道を通る。** 吸着（placementFor）だけ塞いだ時点で
        // 残っていたくぐり 110 通りは**全部この経路**だった ―― どの原子とも競わない遠さに
        // 置かれた原子は結合を持たないので H が上下左右に4本出て、その1本が
        // 既存の結合線に乗る（o-ジニトロベンゼンで実測 7.8px）。
        c.reset();
        withoutRendering(c, () => {
            c.game.userMolecule = new c.W.Molecule();
            c.game.summonMolecule('o-ジニトロベンゼン');
        });
        c.game.updateDrawing();
        // ニトロ基の N が付いた環炭素のまわりを探す（座標を書き写さない ＝ 図が動いても壊れない）
        const mol = c.game.userMolecule;
        const n = mol.atoms.find(a => a.element === 'N');
        assert(n, 'ニトロ基の N が無い（登録図が変わった）');
        const ringC = mol.getNeighbors(n.id).map(x => x.atom).find(a => a.element === 'C');
        assert(ringC, 'N に付いた環炭素が無い（登録図が変わった）');
        missReset(c);
        const spot = findMissSpot(c, ringC.x, ringC.y, { reason: 'hcrossing' });
        assert(spot, '「自由配置で H が乗る」で止まる点が作れなかった（場面の作り方が古い）');
        const before = heavyOf(c).length;
        c.clickAt(spot.x, spot.y);
        await c.tick();
        const msg = toastText(c);
        assert(heavyOf(c).length === before, '止めたはずの点で原子が増えた');
        // 'crossing'（結合線が原子の上を通る）と**言い分ける**。
        // 自由配置には結合線そのものが無いので、あちらの文言だと嘘になる
        assert(msg.includes('水素'), `自由配置のくぐりの文言が違う: ${msg}`);
        assert(!msg.includes('じゃまな枝'), `自由配置なのに「枝をどかせ」と案内している: ${msg}`);
        // 否定対照: 検査を外すと**同じ点に置けてしまい**、H が結合線に乗る
        const legacy = withHit(c, { legacyHydrogenCross: true }, () => {
            c.clickAt(spot.x, spot.y);
            return { added: heavyOf(c).length - before, ...minHydrogenBondGap(c, c.game.userMolecule) };
        });
        assert(legacy.added === 1, `旧挙動で原子が ${legacy.added} 個増えた（1個を期待）`);
        assert(legacy.gap < 12,
            `検査を外しても ${legacy.gap.toFixed(1)}px しか詰まらない ＝ この検査は空振りの緑: ${legacy.detail}`);
    });

    // ===== XL. 大物の登録図（コレステロール・インジゴ。v1220）=====
    //
    // 「化合物作ってみた」の残り2本は**作図はもう通っていた**のに、
    // `compounds.json` に無いせいで「（ライブラリに該当なし）」で終わっていた
    // （`video-scripts/ORDER_drawing_hit_areas.md` §2g）。登録したので、
    // **§2g の手順で組んだ図がその名前を1つに言い切る**ことをここで固定する。
    // α-グルコースのように「〜ほか N 種のどれか（立体で決まります）」に落ちたら、
    // このシリーズの型（描いたそばから名前が出る）に乗らない ＝ 動画が出せない。
    //
    // ⚠ **登録図の側鎖は、実測した一直線からわざと階段へ折ってある。** 理由は XL3。

    // §2g の実測手順そのまま（1手も外していない座標）。
    // `button` は実際のボタンを押す道 ＝ 台本（demos-build.json）と同じ経路
    const XL_BTN = (selector) => ({ type: 'button', selector });
    const XL_TAP = (x, y) => ({ type: 'click', x, y });
    const XL_BOND = (x, y) => ({ type: 'clickBond', x, y });
    const XL_C = XL_BTN('.atom-btn.atom-c');
    const XL_SEL = XL_BTN('#btn-tool-select');
    const XL_BUILDS = [
        {
            name: 'コレステロール', formula: 'C₂₇H₄₆O', atoms: 28, bonds: 31,
            actions: [
                XL_BTN('#btn-clear-all'),
                XL_BTN('.mod-btn[data-module="cyclohexane"]'), XL_TAP(210, 420),
                XL_BTN('.mod-btn[data-module="cyclohexane"]'), XL_TAP(282, 420),
                XL_BTN('.mod-btn[data-module="cyclohexane"]'), XL_TAP(319, 357),
                XL_BTN('.mod-btn[data-module="cyclopentane"]'), XL_TAP(392, 357),
                XL_C, XL_TAP(355, 294),          // C18
                XL_C, XL_TAP(246, 357),          // C19
                XL_BTN('.mod-btn[data-module="oh"]'), XL_TAP(174, 441),
                XL_SEL, XL_BOND(264, 451),       // C5=C6
                XL_C, XL_TAP(415, 290), XL_TAP(408, 245), XL_TAP(450, 290),
                XL_TAP(492, 283), XL_TAP(534, 283), XL_TAP(576, 283),
                XL_TAP(576, 241), XL_TAP(618, 283),
                XL_SEL
            ]
        },
        {
            name: 'インジゴ', formula: 'C₁₆H₁₀N₂O₂', atoms: 20, bonds: 23,
            actions: [
                XL_BTN('#btn-clear-all'),
                XL_BTN('.mod-btn[data-module="cyclohexane"]'), XL_TAP(210, 294),
                XL_BTN('.mod-btn[data-module="cyclopentane"]'), XL_TAP(283, 294),
                XL_BTN('.atom-btn.atom-n'), XL_TAP(286, 260),
                XL_BTN('.atom-btn.atom-o'), XL_TAP(310, 362),
                XL_SEL, XL_BOND(228, 262), XL_BOND(228, 325), XL_BOND(174, 294), XL_BOND(292, 348),
                XL_BTN('.mod-btn[data-module="cyclohexane"]'), XL_TAP(462, 294),
                XL_BTN('.mod-btn[data-module="cyclopentane"]'), XL_TAP(389, 294),
                XL_BTN('.atom-btn.atom-n'), XL_TAP(386, 328),
                XL_BTN('.atom-btn.atom-o'), XL_TAP(362, 226),
                XL_SEL, XL_BOND(444, 262), XL_BOND(444, 325), XL_BOND(498, 294), XL_BOND(379, 240),
                XL_BTN('#btn-tool-bond'),
                { type: 'drag', from: { x: 311, y: 294 }, to: { x: 361, y: 294 } },
                XL_SEL, XL_BOND(336, 294)        // 中央の C2=C2'
            ]
        }
    ];

    test('XL1: §2g の手順で組んだコレステロール／インジゴが、名前を1つに言い切る', async (c) => {
        c.reset();
        const g = c.game, tp = c.W.tutorialPlayer;
        const before = tp.speedScale;
        try {
            tp.speedScale = 1; tp.baseSpeedScale = 1;
            for (const b of XL_BUILDS) {
                g.userMolecule = new c.W.Molecule();
                g.updateDrawing();
                for (const a of b.actions) {
                    await tp.doAction(a, true);
                    // ⚠ **1アクションごとに1ティック空ける。** 詰めて回すと `clickBond` が
                    //    黙って効かず、二重結合の抜けた分子で終わる（N2d と同じ理由）
                    await new Promise(r => setTimeout(r, 1));
                }
                const mol = g.userMolecule;
                assert(mol.atoms.length === b.atoms,
                    `${b.name}: 重原子が ${mol.atoms.length} 個（${b.atoms} 個を期待）＝ 手順が1手抜けている`);
                assert(mol.bonds.length === b.bonds,
                    `${b.name}: 結合が ${mol.bonds.length} 本（${b.bonds} 本を期待）`);
                const chip = c.D.getElementById('compound-name').textContent.trim();
                const formula = c.D.getElementById('compound-formula').textContent.trim();
                assert(formula === b.formula, `${b.name}: 分子式が「${formula}」（「${b.formula}」を期待）`);
                // **言い切ること**が要件。「〜のどれか（立体で決まります）」は動画に乗らない
                assert(chip === b.name, `${b.name}: 名称チップが「${chip}」`);
                // 手で組んだ図と、名前で呼び出す登録図が**同型**か
                const entry = g.getCompoundLibrary().find(e => e.name === b.name);
                assert(entry, `${b.name} がライブラリに無い`);
                assert(c.W.canonicalCode(mol) === entry.code,
                    `${b.name}: 手で組んだ図と登録図の正準コードが違う ＝ 同型でない`);
                assert(c.W.verifyMolecule(mol, entry.mol), `${b.name}: verifyMolecule が通らない`);
            }
        } finally {
            tp.speedScale = before; tp.baseSpeedScale = before;
            g.userMolecule = new c.W.Molecule();
            g.updateDrawing();
        }
    });

    test('XL2: どの登録図も「立体を名前に反映する」の ON/OFF 両方で自分の名前を名乗る', async (c) => {
        c.reset();
        /**
         * **登録図が自分の名前を名乗れないのは、どんな理由でも事故。**
         * コレステロールを実測どおりの座標で入れたとき、**939件中この1件だけ**が
         * 立体 ON で名無しになった（理由は XL3）。件数を数えていなかったので、
         * 気づいたのは偶然だった ＝ 機械に数えさせる。
         */
        const g = c.game, before = g.readStereo;
        const lost = { off: [], on: [] };
        try {
            const byName = new Map(g.getCompoundLibrary().map(e => [e.name, e]));
            [false, true].forEach(on => {
                g.readStereo = on;
                c.W.COMPOUNDS.forEach(entry => {
                    const e = byName.get(entry.name);
                    if (!e) return;
                    if (!g.lookupCompoundName(e.mol)) lost[on ? 'on' : 'off'].push(entry.name);
                });
            });
        } finally {
            g.readStereo = before;
        }
        assert(c.W.COMPOUNDS.length >= 900, `母数が ${c.W.COMPOUNDS.length} 件（900件以上を期待）`);
        assert(lost.off.length === 0, `立体 OFF で名無しの登録図: ${lost.off.slice(0, 5).join(' / ')}`);
        assert(lost.on.length === 0, `立体 ON で名無しの登録図: ${lost.on.slice(0, 5).join(' / ')}`);
    });

    test('XL3: 否定対照 —— 側鎖を実測どおり一直線に戻すと、立体 ON で名無しになる', async (c) => {
        c.reset();
        /**
         * **なぜ登録図が実測の座標と違うのか**を、機械に説明させる。
         *
         * §2g の実測では側鎖を横一直線に置く。その形だと **C17 → C20 が縦から 17°**
         * しか開かず、`_haworthFaceOf`（許容 ±25°）が「ハース環の面」として読んでしまう。
         * すると `stereo` を書いていないのに**エントリに stereoCode が付き**、
         * 立体 ON のときだけ「ユーザーの図の立体コード」との照合が要求される。
         * ユーザー側は C20 をフィッシャー中心としても読むので**コードが揃わず名無し**になる。
         * 側鎖を階段に折って C17 → C20 を 45° にすると面が読めなくなり、
         * 立体の指定を持たない素のエントリ ＝ 構造だけで名乗るようになる。
         */
        const g = c.game;
        const idx = c.W.COMPOUNDS.findIndex(e => e.id === 'cholesterol');
        assert(idx >= 0, 'コレステロールが compounds.json に無い');
        const shipped = c.W.COMPOUNDS[idx];
        const straight = JSON.parse(JSON.stringify(shipped));
        // §2g の実測どおりの側鎖（C20〜C27 が横一直線＋メチル2本が真上）
        [[408.4, 283.1], [408.4, 241.1], [450.4, 283.1], [492.4, 283.1],
         [534.4, 283.1], [576.4, 283.1], [576.4, 241.1], [618.4, 283.1]]
            .forEach(([x, y], k) => { straight.target.atoms[20 + k].x = x; straight.target.atoms[20 + k].y = y; });
        const nameOf = (entry) => {
            c.W.COMPOUNDS[idx] = entry;
            g._compoundLibrary = null;
            g._compoundCodeMap = null;
            return g.lookupCompoundName(g.createTargetFromData({ target: entry.target }));
        };
        const beforeStereo = g.readStereo;
        let now = null, old = null;
        try {
            g.readStereo = true;
            now = nameOf(shipped);
            old = nameOf(straight);
        } finally {
            g.readStereo = beforeStereo;
            c.W.COMPOUNDS[idx] = shipped;
            g._compoundLibrary = null;
            g._compoundCodeMap = null;
            g.getCompoundLibrary();
        }
        assert(now === 'コレステロール', `出荷している登録図が立体 ON で「${now}」＝ 場面の作り方が古い`);
        assert(old === null, `一直線に戻しても「${old}」と名乗る ＝ XL2 は空振りの緑`);
    });

